func newCustomer() unsafe.Pointer { return unsafe.Pointer(new(fleet.Customer)) }

func newNCustomer(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]fleet.Customer, n)))
}

func ptrCustomer(p unsafe.Pointer, c int32) any {
	r := (*fleet.Customer)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return &r.Name
	case 4:
		return &r.Code
	case 5:
		return &r.Email
	case 6:
		return &r.Version
	case 7:
		return &r.CreatedAt
	case 8:
		return &r.UpdatedAt
	}
	return nil
}

func valueCustomer(p unsafe.Pointer, c int32) any {
	r := (*fleet.Customer)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return r.Name
	case 4:
		return r.Code
	case 5:
		if r.Email == nil {
			return nil
		}
		return *r.Email
	case 6:
		return r.Version
	case 7:
		return r.CreatedAt
	case 8:
		return r.UpdatedAt
	}
	return nil
}

