func ptrLocation(p unsafe.Pointer, c int32) any {
	r := (*fleet.Location)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return &r.Name
	case 4:
		return &r.City
	}
	return nil
}

func valueLocation(p unsafe.Pointer, c int32) any {
	r := (*fleet.Location)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return r.Name
	case 4:
		return r.City
	}
	return nil
}

