func newMove() unsafe.Pointer { return unsafe.Pointer(new(fleet.Move)) }

func newNMove(n int) unsafe.Pointer { return unsafe.Pointer(unsafe.SliceData(make([]fleet.Move, n))) }

func ptrMove(p unsafe.Pointer, c int32) any {
	r := (*fleet.Move)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 4:
		return &r.Sequence
	case 5:
		return (*string)(unsafe.Pointer(&r.Status))
	case 6:
		return &r.Loaded
	case 7:
		return &r.CreatedAt
	}
	return nil
}

func valueMove(p unsafe.Pointer, c int32) any {
	r := (*fleet.Move)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		return r.Sequence
	case 5:
		return string(r.Status)
	case 6:
		return r.Loaded
	case 7:
		return r.CreatedAt
	}
	return nil
}

func attachMove(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*fleet.Move)(p)
	switch rel {
	case 0:
		r.Shipment = (*fleet.Shipment)(child)
	case 1:
		r.Stops = append(r.Stops, (*fleet.Stop)(child))
	case 2:
		r.FirstStop = (*fleet.Stop)(child)
	}
}

