func newStop() unsafe.Pointer { return unsafe.Pointer(new(fleet.Stop)) }

func newNStop(n int) unsafe.Pointer { return unsafe.Pointer(unsafe.SliceData(make([]fleet.Stop, n))) }

func ptrStop(p unsafe.Pointer, c int32) any {
	r := (*fleet.Stop)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.MoveID))
	case 4:
		return (*string)(unsafe.Pointer(&r.LocationID))
	case 5:
		return &r.Sequence
	case 6:
		return &r.Kind
	case 7:
		return &r.ArrivedAt
	}
	return nil
}

func valueStop(p unsafe.Pointer, c int32) any {
	r := (*fleet.Stop)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.MoveID)
	case 4:
		return string(r.LocationID)
	case 5:
		return r.Sequence
	case 6:
		return r.Kind
	case 7:
		if r.ArrivedAt == nil {
			return nil
		}
		return *r.ArrivedAt
	}
	return nil
}

func attachStop(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*fleet.Stop)(p)
	switch rel {
	case 0:
		r.Location = (*fleet.Location)(child)
	}
}

