func newTag() unsafe.Pointer { return unsafe.Pointer(new(fleet.Tag)) }

func newNTag(n int) unsafe.Pointer { return unsafe.Pointer(unsafe.SliceData(make([]fleet.Tag, n))) }

func ptrTag(p unsafe.Pointer, c int32) any {
	r := (*fleet.Tag)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return &r.Name
	}
	return nil
}

func valueTag(p unsafe.Pointer, c int32) any {
	r := (*fleet.Tag)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return r.Name
	}
	return nil
}

