func newWorker() unsafe.Pointer { return unsafe.Pointer(new(fleet.Worker)) }

func newNWorker(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]fleet.Worker, n)))
}

func ptrWorker(p unsafe.Pointer, c int32) any {
	r := (*fleet.Worker)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (**string)(unsafe.Pointer(&r.ManagerID))
	case 4:
		return &r.FirstName
	case 5:
		return &r.LastName
	case 6:
		return &r.WholeName
	case 7:
		return &r.HiredAt
	}
	return nil
}

func valueWorker(p unsafe.Pointer, c int32) any {
	r := (*fleet.Worker)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		if r.ManagerID == nil {
			return nil
		}
		return string(*r.ManagerID)
	case 4:
		return r.FirstName
	case 5:
		return r.LastName
	case 6:
		return r.WholeName
	case 7:
		return r.HiredAt
	}
	return nil
}

func attachWorker(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*fleet.Worker)(p)
	switch rel {
	case 0:
		r.Manager = (*fleet.Worker)(child)
	}
}

func beforeSaveWorker(ctx context.Context, p unsafe.Pointer) error {
	return (*fleet.Worker)(p).BeforeSave(ctx)
}

func afterLoadWorker(ctx context.Context, p unsafe.Pointer) error {
	return (*fleet.Worker)(p).AfterLoad(ctx)
}

func init() {
	contactsTable.Relations[0].Target = CustomersSchema()
	leavesTable.Relations[0].Target = LeaveEntriesSchema()
	leavesTable.Relations[1].Target = LeaveEntriesSchema()
	leaveEntriesTable.Relations[0].Target = LeavesSchema()
	movesTable.Relations[0].Target = ShipmentsSchema()
	movesTable.Relations[1].Target = StopsSchema()
	movesTable.Relations[2].Target = StopsSchema()
	notesTable.Relations[0].Target = CustomersSchema()
	shipmentsTable.Relations[0].Target = CustomersSchema()
	shipmentsTable.Relations[1].Target = CustomersSchema()
	shipmentsTable.Relations[2].Target = MovesSchema()
	shipmentsTable.Relations[3].Target = TagsSchema()
	shipmentsTable.Relations[4].Target = StopsSchema()
	shipmentsTable.Relations[5].Target = StopsSchema()
	stopsTable.Relations[0].Target = LocationsSchema()
	workersTable.Relations[0].Target = WorkersSchema()
}

